const cells = Array.from(document.querySelectorAll(".cell"));
const statusElement = document.getElementById("status-message");

// global variables
let board = [
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
];
let players = ["A", "B"];
let currentPlayerIndex = 0
let currentPlayer = players[currentPlayerIndex];
let statusMessage = `Status: Player ${currentPlayer} Turn`;
let turnClicks = []; // stores the two cell indices for the current turn
let gameOver = false;


// connect the HTML + JS
cells.forEach((cell) => {
  cell.addEventListener("click", (event) => {
    const index = Number(event.currentTarget.dataset.index);
    onMove(index);
  });
});

// Show the initial status message before any click
renderBoard();

// JS functions
function playMove(cellIndex) {
  if (gameOver) {
    return;
  }
  console.log("User clicked on cell:", cellIndex);

  // Convert cellIndex (0-24) to board coordinates
  const row = Math.floor(cellIndex / 5);
  const col = cellIndex % 5;

  // Only allow placing on empty cells
  if (board[row][col] !== "") {
    return;
  }

  // Store the click for this turn
  turnClicks.push(cellIndex);

  // Mark the cell for the current player
  board[row][col] = currentPlayer;

  // Check for win after each move
  if (checkWinner(currentPlayer)) {
    statusMessage = `Status: Player ${currentPlayer} Wins!`;
    gameOver = true;
    return;
  }

  // Check for draw (board full)
  if (isBoardFull()) {
    statusMessage = "Status: Tie Game!";
    gameOver = true;
    return;
  }

  if (turnClicks.length === 2) {
    // End of turn: switch player
    currentPlayerIndex = 1 - currentPlayerIndex;
    currentPlayer = players[currentPlayerIndex];
    statusMessage = `Status: Player ${currentPlayer} Turn`;
    turnClicks = [];
  } else {
    // Still the same player's turn, waiting for second click
    statusMessage = `Status: Player ${currentPlayer} Turn`;
  }
}

function renderBoard() {
  console.log("Displaying the board");
  // Update the UI to reflect the board state
  for (let i = 0; i < 25; i++) {
    const row = Math.floor(i / 5);
    const col = i % 5;
    cells[i].textContent = board[row][col];
  }
  // Display status message in the <p> tag
  if (statusElement) {
    statusElement.textContent = statusMessage;
  }
  console.log(statusMessage);
}

// Check for five in a row horizontally or vertically for the given player
function checkWinner(player) {
  // Check rows
  for (let row = 0; row < 5; row++) {
    let win = true;
    for (let col = 0; col < 5; col++) {
      if (board[row][col] !== player) {
        win = false;
        break;
      }
    }
    if (win) return true;
  }
  // Check columns
  for (let col = 0; col < 5; col++) {
    let win = true;
    for (let row = 0; row < 5; row++) {
      if (board[row][col] !== player) {
        win = false;
        break;
      }
    }
    if (win) return true;
  }
  return false;
}

// Check if the board is full (no empty cells)
function isBoardFull() {
  for (let row = 0; row < 5; row++) {
    for (let col = 0; col < 5; col++) {
      if (board[row][col] === "") {
        return false;
      }
    }
  }
  return true;
}

function onMove(cellIndex) {
  playMove(cellIndex);
  renderBoard();
}"}

