let board = [
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
];
let currentPlayer = "A"; // Start with Player A
let symbolsPlacedThisTurn = 0; // Track how many symbols placed in current turn
let statusMessage = "";
let gameOver = false;

// connect the HTML + JS
cells.forEach((cell) => {
  cell.addEventListener("click", (event) => {
    const index = Number(event.currentTarget.dataset.index);
    onMove(index);
  });
});

// JS functions
function playMove(cellIndex) {
  if (gameOver) {
    return;
  }
  // console.log("User clicked on cell:", cellIndex);

  // Convert cellIndex (0-24) to board coordinates
  const row = Math.floor(cellIndex / 5);
  const col = cellIndex % 5;

  // If cell already has a symbol, do nothing
  if (board[row][col] !== "") {
    return;
  }

  // Place current player's symbol
  board[row][col] = currentPlayer;
  symbolsPlacedThisTurn++;

  // Check for win after placing
  if (checkWin(currentPlayer)) {
    gameOver = true;
    statusMessage = `Player ${currentPlayer} wins!`;
    renderBoard();
    setTimeout(() => alert(statusMessage), 100);
    return;
  }

  // Check for tie (no empty cells left)
  if (isBoardFull()) {
    gameOver = true;
    statusMessage = "Tie Game!";
    renderBoard();
    setTimeout(() => alert(statusMessage), 100);
    return;
  }

  // After two placements, switch player
  if (symbolsPlacedThisTurn >= 2) {
    currentPlayer = currentPlayer === "A" ? "B" : "A";
    symbolsPlacedThisTurn = 0;
  }
}

function renderBoard() {
  // Update the UI to reflect the board state
  for (let i = 0; i < 25; i++) {
    const row = Math.floor(i / 5);
    const col = i % 5;
    cells[i].textContent = board[row][col];
  }

  // Update the status message
  if (gameOver) {
    statusElement.textContent = `Status: ${statusMessage}`;
  } else {
    statusElement.textContent = `Status: Player ${currentPlayer} Turn`;
  }
}

function onMove(cellIndex) {
  playMove(cellIndex);
  renderBoard();
}

// Check for five in a row horizontally or vertically for the given player
function checkWin(player) {
  // Check rows
  for (let row = 0; row < 5; row++) {
    let count = 0;
    for (let col = 0; col < 5; col++) {
      if (board[row][col] === player) {
        count++;
      }
    }
    if (count === 5) {
      return true;
    }
  }
  // Check columns
  for (let col = 0; col < 5; col++) {
    let count = 0;
    for (let row = 0; row < 5; row++) {
      if (board[row][col] === player) {
        count++;
      }
    }
    if (count === 5) {
      return true;
    }
  }
  return false;
}

// Check if the board is full (tie)
function isBoardFull() {
  for (let row = 0; row < 5; row++) {
    for (let col = 0; col < 5; col++) {
      if (board[row][col] === "") {
        return false;
      }
    }
  }
  return true;
}"}

