  const statusEl = document.getElementById("status");
  const cells = Array.from(document.querySelectorAll(".cell"));
  const resetBtn = document.getElementById("resetBtn");

  const BOARD_SIZE = 5;
  const CORNER_INDEXES = [0, 4, 20, 24];

  let board = new Array(cells.length).fill("");
  let currentPlayer = "A";
  let gameOver = false;

  function buildWinningLines() {
    const lines = [];

    // rows
    for (let row = 0; row < BOARD_SIZE; row += 1) {
      const line = [];
      for (let col = 0; col < BOARD_SIZE; col += 1) {
        line.push(row * BOARD_SIZE + col);
      }
      lines.push(line);
    }

    // columns
    for (let col = 0; col < BOARD_SIZE; col += 1) {
      const line = [];
      for (let row = 0; row < BOARD_SIZE; row += 1) {
        line.push(row * BOARD_SIZE + col);
      }
      lines.push(line);
    }

    // main diagonal
    lines.push(
      Array.from({ length: BOARD_SIZE }, (_, i) => i * (BOARD_SIZE + 1))
    );

    // anti-diagonal
    lines.push(
      Array.from({ length: BOARD_SIZE }, (_, i) => (i + 1) * (BOARD_SIZE - 1))
    );

    return lines;
  }

  const WINNING_LINES = buildWinningLines();

  function setStatus(message) {
    statusEl.textContent = message;
  }

  function hasLineWin(player) {
    return WINNING_LINES.some((line) =>
      line.every((index) => board[index] === player)
    );
  }

  function hasCornerWin(player) {
    return CORNER_INDEXES.every((index) => board[index] === player);
  }

  function hasWinner(player) {
    return hasLineWin(player) || hasCornerWin(player);
  }

  function switchPlayer() {
    currentPlayer = currentPlayer === "A" ? "B" : "A";
  }

  function renderMove(cell, player) {
    cell.textContent = player;
    cell.classList.remove("player-a", "player-b");
    cell.classList.add(player === "A" ? "player-a" : "player-b");
  }

  function clearCell(cell) {
    cell.textContent = "";
    cell.classList.remove("player-a", "player-b");
  }

  function handleCellClick(event) {
    const cell = event.currentTarget;
    const index = Number(cell.dataset.index);

    if (gameOver || board[index]) {
      return;
    }

    board[index] = currentPlayer;
    renderMove(cell, currentPlayer);

    if (hasWinner(currentPlayer)) {
      gameOver = true;
      setStatus(`Status: Player ${currentPlayer} Wins!`);
      return;
    }

    if (board.every(Boolean)) {
      gameOver = true;
      setStatus("Status: Draw!");
      return;
    }

    switchPlayer();
    setStatus(`Status: Player ${currentPlayer} Turn`);
  }

  function resetGame() {
    board = new Array(cells.length).fill("");
    currentPlayer = "A";
    gameOver = false;

    cells.forEach(clearCell);
    setStatus("Status: Player A Turn");
  }

  cells.forEach((cell) => {
    cell.addEventListener("click", handleCellClick);
  });

  if (resetBtn) {
    resetBtn.addEventListener("click", resetGame);
  }

  resetGame();
});"}

