const cells = Array.from(document.querySelectorAll(".cell"));
// const statusElement = ...;

/*
Modified Tic Tac Toe:
- 5x5 board
- Need 5 in a row to win
- Each player (A, B) places two pieces per turn
*/

let board = [
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
];
let currentPlayer = "A";
let piecesPlacedThisTurn = 0;
let statusMessage = "Player A's turn: place 2 pieces";

// connect the HTML + JS
cells.forEach((cell) => {
  cell.addEventListener("click", (event) => {
    const index = Number(event.currentTarget.dataset.index);
    onMove(index);
  });
});

// JS functions
function playMove(cellIndex) {
  console.log("User clicked on cell:", cellIndex);

  // Convert cellIndex (0-24) to row,col
  const row = Math.floor(cellIndex / 5);
  const col = cellIndex % 5;

  // Ignore if cell is already filled or game is over
  if (board[row][col] !== "" || checkWinner(board) || isBoardFull()) {
    return;
  }

  // Place current player's piece
  board[row][col] = currentPlayer;
  piecesPlacedThisTurn++;

  // After each placement, check for a winner
  const winner = checkWinner(board);
  if (winner) {
    statusMessage = `Player ${winner} wins!`;
    return;
  }

  // Check for tie after move
  if (isBoardFull()) {
    statusMessage = "Tie Game";
    return;
  }

  // If both pieces placed, switch player
  if (piecesPlacedThisTurn === 2) {
    currentPlayer = currentPlayer === "A" ? "B" : "A";
    piecesPlacedThisTurn = 0;
    statusMessage = `Player ${currentPlayer}'s turn: place 2 pieces`;
  } else {
    statusMessage = `Player ${currentPlayer}'s turn: place 1 more piece`;
  }
}

function renderBoard() {
  // Update the board UI
  for (let i = 0; i < 25; i++) {
    const cell = cells[i];
    const row = Math.floor(i / 5);
    const col = i % 5;
    cell.textContent = board[row][col];
  }

  // Update the heading or add a status display
  let statusEl = document.getElementById("status-message");
  if (!statusEl) {
    statusEl = document.createElement("div");
    statusEl.id = "status-message";
    statusEl.style.marginTop = "16px";
    document.querySelector(".container").appendChild(statusEl);
  }
  statusEl.textContent = statusMessage;
}

function onMove(cellIndex) {
  playMove(cellIndex);
  renderBoard();
}

/*
Check for 5 in a row (vertical or horizontal only).
Only the player with five in a row or five in a column wins.
*/
function checkWinner(board) {
  // Check rows (horizontal)
  for (let row = 0; row < 5; row++) {
    for (let col = 0; col <= 0; col++) {
      const player = board[row][col];
      if (
        player &&
        board[row][col + 1] === player &&
        board[row][col + 2] === player &&
        board[row][col + 3] === player &&
        board[row][col + 4] === player
      ) {
        return player;
      }
    }
  }
  // Check columns (vertical)
  for (let col = 0; col < 5; col++) {
    for (let row = 0; row <= 0; row++) {
      const player = board[row][col];
      if (
        player &&
        board[row + 1][col] === player &&
        board[row + 2][col] === player &&
        board[row + 3][col] === player &&
        board[row + 4][col] === player
      ) {
        return player;
      }
    }
  }
  return null;
}

// Initial render
renderBoard();

// Helper function to check if the board is full (tie)
function isBoardFull() {
  for (let row = 0; row < 5; row++) {
    for (let col = 0; col < 5; col++) {
      if (board[row][col] === "") {
        return false;
      }
    }
  }
  return true;
}"}

