    board[row][col] = currentPlayer;
    placedThisTurn += 1;

    // Update the cell visually
    cells[cellIndex].className = currentPlayer === 'A' ? 'a' : 'b';

    // Check for winner after each move
    const winner = checkWinner();
    if (winner) {
      statusMessage = `Player ${winner} wins!`;
      gameOver = true;
      renderBoard();
      return;
    } else if (isBoardFull()) {
      statusMessage = "It's a tie!";
      gameOver = true;
      renderBoard();
      return;
    }

    // If player has placed 2 symbols, switch turn
    if (placedThisTurn === 2) {
      currentPlayer = currentPlayer === "A" ? "B" : "A";
      placedThisTurn = 0;
    }
  }
}

function renderBoard() {
  console.log("Displaying the board");
  // Update all cells to match board state
  for (let i = 0; i < 25; i++) {
    const row = Math.floor(i / 5);
    const col = i % 5;
    cells[i].textContent = board[row][col];
    cells[i].disabled = !!board[row][col] || gameOver;
  }
  // Update status message
  if (gameOver) {
    statusElement.textContent = (
      statusMessage === "It's a tie!"
        ? "Status: Tie Game!"
        : "Status: " + statusMessage.replace(" wins!", " Wins!")
    );
  } else {
    statusElement.textContent = `Status: Player ${currentPlayer} turn`;
  }
}

function onMove(cellIndex) {
  playMove(cellIndex);
  renderBoard();
}

resetBtn.addEventListener('click', function() {
  board = [
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ];
  currentPlayer = "A";
  placedThisTurn = 0; // counts how many symbols placed in current turn (max 2)
  statusMessage = "";
  gameOver = false;

  // Set initial status message
  statusElement.textContent = "Status: Player A turn";
  renderBoard();
});"}

