  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
];
let currentPlayer = "A";
let game_Over = false;

// connect the HTML + JS
cells.forEach((cell, index) => {
  cell.addEventListener("click", () => {
    if (!game_Over) {
      onMove(index);
    }
  });
});

// Requirement 3: Reset Functionality
resetBtn.addEventListener("click", () => {
  board = [
    ["", "", "", "", ""],
    ["", "", "", "", ""],
    ["", "", "", "", ""],
    ["", "", "", "", ""],
    ["", "", "", "", ""],
  ];
  currentPlayer = "A";
  game_Over = false;
  statusElement.textContent = "Status: Player A Turn";

  cells.forEach(cell => {
    cell.textContent = "";
    cell.classList.remove("player-a", "player-b"); // Requirement 2: Clean classes
  });
});

// JS functions
function playMove(cellIndex) {
  const row = Math.floor(cellIndex / 5);
  const col = cellIndex % 5;

  if (game_Over || board[row][col] !== "") return;

  board[row][col] = currentPlayer;

  // Requirement 2: Apply CSS colors via classList (NOT .style)
  if (currentPlayer === "A") {
    cells[cellIndex].classList.add("player-a");
  } else {
    cells[cellIndex].classList.add("player-b");
  }

  if (checkWin(currentPlayer)) {
    game_Over = true;
    statusElement.textContent = "Status: Player " + currentPlayer + " Wins!";
    return;
  }

