  currentPlayer = currentPlayer === "A" ? "B" : "A";
  statusElement.textContent = "Status: Player " + currentPlayer + " Turn";
}

function checkWin(player) {
  // 1. Check Rows
  for (let r = 0; r < 5; r++) {
    if (board[r].every(cell => cell === player)) return true;
  }

  // 2. Check Columns
  for (let c = 0; c < 5; c++) {
    if (board.every(row => row[c] === player)) return true;
  }

  // 3. Check Diagonals
  const diag1 = [board[0][0], board[1][1], board[2][2], board[3][3], board[4][4]];
  const diag2 = [board[0][4], board[1][3], board[2][2], board[3][1], board[4][0]];
  if (diag1.every(cell => cell === player) || diag2.every(cell => cell === player)) return true;

  // Requirement 1: Check Four Corners
  const corners = [board[0][0], board[0][4], board[4][0], board[4][4]];
  if (corners.every(cell => cell === player)) return true;

  return false;
}

