let board = [
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
];
let currentPlayer = "A";
let movesThisTurn = 0;
let gameActive = true;
let statusMessage = "";

cells.forEach((cell) => {
  cell.addEventListener("click", (event) => {
    if (!gameActive) return;

    const index = Number(event.currentTarget.dataset.index);
    onMove(index);
  });
});

function playMove(cellIndex) {
  const row = Math.floor(cellIndex / 5);
  const col = cellIndex % 5;

  if (board[row][col] !== "") {
    return false;
  }

  board[row][col] = currentPlayer;

  movesThisTurn++;

  return true;
}

function renderBoard() {
  cells.forEach((cell, index) => {
    const row = Math.floor(index / 5);
    const col = index % 5;
    cell.textContent = board[row][col];
  });
}

function checkWinOrTie() {

  for (let r = 0; r < 5; r++) {
    if (
      board[r][0] !== "" &&
      board[r][0] === board[r][1] &&
      board[r][1] === board[r][2] &&
      board[r][2] === board[r][3] &&
      board[r][3] === board[r][4]
    ) {
      return board[r][0]; 
    }
  }
  for (let c = 0; c < 5; c++) {
    if (
      board[0][c] !== "" &&
      board[0][c] === board[1][c] &&
      board[1][c] === board[2][c] &&
      board[2][c] === board[3][c] &&
      board[3][c] === board[4][c]
    ) {
      return board[0][c]; 
    }
  }
  let isTie = true;
  for (let r = 0; r < 5; r++) {
    for (let c = 0; c < 5; c++) {
      if (board[r][c] === "") {
        isTie = false;
        break;
      }
    }
  }

  if (isTie) {
    return "Tie";
  }
  return null;
}

function updateStatusMessage(result) {
  if (result === "A") {
    statusElement.textContent = "Status: Player A Wins!";
    gameActive = false;
  } else if (result === "B") {
    statusElement.textContent = "Status: Player B Wins!";
    gameActive = false;
  } else if (result === "Tie") {
    statusElement.textContent = "Status: Tie Game!";
    gameActive = false;
  } else {
    statusElement.textContent = `Status: Player ${currentPlayer} Turn`;
  }
}

function onMove(cellIndex) {
  const moveSuccessful = playMove(cellIndex);

  if (moveSuccessful) {
    renderBoard();

    const result = checkWinOrTie();

    if (result) {
      updateStatusMessage(result);
    } else {
      if (movesThisTurn === 2) {
        currentPlayer = currentPlayer === "A" ? "B" : "A";
        movesThisTurn = 0;
      }
      updateStatusMessage(null);
    }
  }
}
