  for (let row = 0; row < 5; row++){
    let rowWin = true;
    for (let col = 0; col < 5; col++){
      if (board[row][col] != player) {
        rowWin = false;
      }
    }
    if(rowWin){
      return true;
    }
  }


  for (let col = 0; col < 5; col++){
    let colWin = true;
    for (let row = 0; row < 5; row++){
      if (board[row][col] != player) {
        colWin = false;
      }
    }
    if(colWin){
      return true;
    }
  }

  if (
    board[0][0] === player &&
    board[0][4] === player &&
    board[4][0] === player &&
    board[4][4] === player  
  ){
    return true;
  }

  return false;

}

renderBoard();

"}

