const statusElement = document.getElementById("status");
const resetBtn = document.getElementById("reset-btn");

// State
let board = Array(5).fill(null).map(() => Array(5).fill(""));
let currentPlayer = "A";
let gameFinished = false;

// Wire up events
cells.forEach(cell => {
  cell.addEventListener("click", () => {
    const idx = Number(cell.dataset.index);
    onMove(idx);
  });
});

if (resetBtn) {
  resetBtn.addEventListener("click", resetGame);
}

// Main move handler
function onMove(cellIndex) {
  if (gameFinished) return;

  const row = Math.floor(cellIndex / 5);
  const col = cellIndex % 5;

  if (board[row][col] !== "") return; // no overwrite

  board[row][col] = currentPlayer;
  renderBoard();

  const winner = checkWinner();
  if (winner) {
    statusElement.textContent = `Status: Player ${winner} Wins!`;
    gameFinished = true;
    return;
  }

  // tie
  if (board.flat().every(c => c !== "")) {
    statusElement.textContent = "Status: Tie Game!";
    gameFinished = true;
    return;
  }

  // next turn
  currentPlayer = currentPlayer === "A" ? "B" : "A";
  statusElement.textContent = `Status: Player ${currentPlayer}'s Turn`;
}

// Render UI from state
function renderBoard() {
  cells.forEach((cell, i) => {
    const row = Math.floor(i / 5);
    const col = i % 5;
    const val = board[row][col];

    cell.textContent = val;

    // Do NOT set colors directly in JS. Toggle semantic classes.
    cell.classList.remove("A", "B");
    if (val === "A" || val === "B") cell.classList.add(val);
  });
}

// Determine winner: rows, columns, and 4-corners rule
function checkWinner() {
  // rows/columns (non-empty and all equal)
  for (let i = 0; i < 5; i++) {
    if (board[i][0] && board[i].every(c => c === board[i][0])) return board[i][0];
    const colVal = board[0][i];
    if (colVal && board.every(r => r[i] === colVal)) return colVal;
  }

  // corners rule
  const c00 = board[0][0];
  const c04 = board[0][4];
  const c40 = board[4][0];
  const c44 = board[4][4];
  if (c00 && c00 === c04 && c00 === c40 && c00 === c44) return c00;

  return null;
}

// Reset everything without reloading
function resetGame() {
  board = Array(5).fill(null).map(() => Array(5).fill(""));
  currentPlayer = "A";
  gameFinished = false;
  renderBoard();
  statusElement.textContent = "Status: Player A's Turn";
}

// Initial paint
renderBoard();
statusElement.textContent = "Status: Player A's Turn";"}

