const statusElement = document.getElementById("status");
const cells = Array.from(document.querySelectorAll(".cell"));
const resetBtn = document.getElementById("reset-btn");

// global variables
let board = Array.from({ length: 5 }, () => Array(5).fill(""));
let currentPlayer = "A";
let moveCount = 0;
let gameOver = false;

// connect events
cells.forEach((cell) => {
  cell.addEventListener("click", (event) => {
    const index = Number(event.currentTarget.dataset.index);
    onMove(index);
  });
});

resetBtn.addEventListener("click", resetGame);

// functions
function playMove(cellIndex) {
  if (gameOver) return;

  const row = Math.floor(cellIndex / 5);
  const col = cellIndex % 5;

  if (board[row][col] !== "") return;

  board[row][col] = currentPlayer;
  moveCount++;

  checkWinner();

  if (!gameOver && moveCount % 2 === 0) {
    currentPlayer = currentPlayer === "A" ? "B" : "A";
  }
}

function renderBoard() {
  cells.forEach((cell, index) => {
    const row = Math.floor(index / 5);
    const col = index % 5;
    const value = board[row][col];

    cell.textContent = value;
    cell.classList.remove("A", "B");

    if (value) {
      cell.classList.add(value);
    }
  });

  if (!gameOver) {
    statusElement.textContent = `Status: Player ${currentPlayer} Turn`;
  }
}

function onMove(cellIndex) {
  playMove(cellIndex);
  renderBoard();
}

function checkWinner() {
  // 行
  for (let i = 0; i < 5; i++) {
    if (board[i][0] && board[i].every(cell => cell === board[i][0])) {
      gameOver = true;
      statusElement.textContent = `Status: Player ${board[i][0]} Wins!`;
      return;
    }
  }

  // 列
  for (let j = 0; j < 5; j++) {
    const col = board.map(row => row[j]);
    if (col[0] && col.every(cell => cell === col[0])) {
      gameOver = true;
      statusElement.textContent = `Status: Player ${col[0]} Wins!`;
      return;
    }
  }

  // 四角胜利 ⭐（新 requirement）
  const corners = [
    board[0][0],
    board[0][4],
    board[4][0],
    board[4][4],
  ];

  if (corners[0] && corners.every(c => c === corners[0])) {
    gameOver = true;
    statusElement.textContent = `Status: Player ${corners[0]} Wins!`;
    return;
  }

  // 平局
  if (moveCount === 25) {
    gameOver = true;
    statusElement.textContent = "Status: Tie Game!";
  }
}

function resetGame() {
  board = Array.from({ length: 5 }, () => Array(5).fill(""));
  currentPlayer = "A";
  moveCount = 0;
  gameOver = false;

  statusElement.textContent = "Status: Player A Turn";

  cells.forEach(cell => {
    cell.textContent = "";
    cell.classList.remove("A", "B");
  });
}"}

