const statusElement = document.querySelector("#status");
const resetButton = document.querySelector("#reset-btn");

let board = [
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
];

