let gameOver = false;
let statusMessage = "Player A Turn";

cells.forEach((cell) => {
  cell.addEventListener("click", (event) => {
    const index = Number(event.currentTarget.dataset.index);
    onMove(index);
  });
});

function playMove(cellIndex) {
  if (gameOver) return;

  const row = Math.floor(cellIndex / 5);
  const col = cellIndex % 5;

  if (board[row][col] !== "") return;

  board[row][col] = currentPlayer;
  movesThisTurn += 1;

  const winner = checkWinner();
  if (winner) {
    gameOver = true;
    statusMessage = `Player ${winner} Wins!`;
    return;
  }

  if (isBoardFull()) {
    gameOver = true;
    statusMessage = "Tie Game!";
    return;
  }

  if (movesThisTurn === 2) {
    currentPlayer = currentPlayer === "A" ? "B" : "A";
    movesThisTurn = 0;
  }

  statusMessage = `Player ${currentPlayer} Turn`;
}

function renderBoard() {
  cells.forEach((cell, index) => {
    const row = Math.floor(index / 5);
    const col = index % 5;
    const value = board[row][col];

    cell.textContent = value;
    cell.classList.remove("player-a", "player-b");

    if (value === "A") {
      cell.classList.add("player-a");
    } else if (value === "B") {
      cell.classList.add("player-b");
    }
  });

  statusElement.textContent = `Status: ${statusMessage}`;
}

function checkWinner() {
  for (let row = 0; row < 5; row++) {
    const first = board[row][0];
    if (first !== "" && board[row].every((cell) => cell === first)) {
      return first;
    }
  }

  for (let col = 0; col < 5; col++) {
    const first = board[0][col];
    if (first === "") continue;

    let allMatch = true;
    for (let row = 1; row < 5; row++) {
      if (board[row][col] !== first) {
        allMatch = false;
        break;
      }
    }

    if (allMatch) return first;
  }

  const topLeft = board[0][0];
  const topRight = board[0][4];
  const bottomLeft = board[4][0];
  const bottomRight = board[4][4];

  if (
    topLeft !== "" &&
    topLeft === topRight &&
    topLeft === bottomLeft &&
    topLeft === bottomRight
  ) {
    return topLeft;
  }

  return null;
}

function isBoardFull() {
  return board.every((row) => row.every((cell) => cell !== ""));
}

function onMove(cellIndex) {
  playMove(cellIndex);
  renderBoard();
}

renderBoard();"}

